import SwiftUIstruct TodayTimeline: View{    @Bindable    var v = TodayViewModel.shared        @State    private var showAlert: Bool = false        @State    private var selectedItem: ListItemContent?        var body: some View    {        VStack(alignment: .leading, spacing: 10)        {            HStack            {                Text("Today")                    .font(.footnote)                    .bold()                                Spacer()                                if !v.timeline.isEmpty                {                    Text("\(v.timeline.count) logged")                        .font(.footnote)                        .foregroundStyle(.secondary)                        .contentTransition(.numericText())                        .animation(.snappy, value: v.timeline.count)                }            }                        if v.timeline.isEmpty            {                Text("Start Logging !!")                    .font(.footnote)                    .foregroundStyle(.secondary)                    .padding(.vertical, 12)            } else            {                VStack(spacing: 0)                {                    ForEach(v.timeline, id: \.compositeId)                    { item in                        TimelineRow(                            item: item,                            isFirst: item.compositeId == v.timeline.first?.compositeId,                            isLast: item.compositeId == v.timeline.last?.compositeId                        ) { toDelete in                            selectedItem = toDelete                            showAlert = true                        }                        .transition(.asymmetric(                            insertion: .opacity.combined(with: .move(edge: .top)),                            removal: .opacity.combined(with: .scale(scale: 0.95))                        ))                    }                }            }        }        .animation(.spring(response: 0.35, dampingFraction: 0.8), value: v.timeline.map(\.compositeId))        .padding(.top)        .alert("Delete log?", isPresented: $showAlert)        {            Button("Delete", role: .destructive)            {                if let selectedItem {                    v.deleteTimelineItem(selectedItem)                }            }                        Button("Cancel", role: .cancel) {}        }    }}